def compute(vars):
    difference = vars["v2"] - vars["v1"]
    return {
        "value": difference,
        "trace": {
            "2018_dividends_paid_in_cash": vars["v1"],
            "2019_dividends_paid_in_cash": vars["v2"],
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
